from math import comb

def pass_at_k(total, correct, k):
    if not 0 <= correct <= total or not 1 <= k <= total:
        raise ValueError("invalid sample counts")
    failed_groups = comb(total - correct, k)
    return 1 - failed_groups / comb(total, k)

assert pass_at_k(5, 0, 2) == 0
assert pass_at_k(5, 4, 2) == 1
print(pass_at_k(5, 2, 1), pass_at_k(5, 2, 2))
